Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: openvswitch: fix middle attribute validation in
 push_nsh() action

The push_nsh() action structure looks like this:

 OVS_ACTION_ATTR_PUSH_NSH(OVS_KEY_ATTR_NSH(OVS_NSH_KEY_ATTR_BASE,...))

The outermost OVS_ACTION_ATTR_PUSH_NSH attribute is OK'ed by the
nla_for_each_nested() inside __ovs_nla_copy_actions().  The innermost
OVS_NSH_KEY_ATTR_BASE/MD1/MD2 are OK'ed by the nla_for_each_nested()
inside nsh_key_put_from_nlattr().  But nothing checks if the attribute
in the middle is OK.  We don't even check that this attribute is the
OVS_KEY_ATTR_NSH.  We just do a double unwrap with a pair of nla_data()
calls - first time directly while calling validate_push_nsh() and the
second time as part of the nla_for_each_nested() macro, which isn't
safe, potentially causing invalid memory access if the size of this
attribute is incorrect.  The failure may not be noticed during
validation due to larger netlink buffer, but cause trouble later during
action execution where the buffer is allocated exactly to the size:

 BUG: KASAN: slab-out-of-bounds in nsh_hdr_from_nlattr+0x1dd/0x6a0 [openvswitch]
 Read of size 184 at addr ffff88816459a634 by task a.out/22624

 CPU: 8 UID: 0 PID: 22624 6.18.0-rc7+ #115 PREEMPT(voluntary)
 Call Trace:
  <TASK>
  dump_stack_lvl+0x51/0x70
  print_address_description.constprop.0+0x2c/0x390
  kasan_report+0xdd/0x110
  kasan_check_range+0x35/0x1b0
  __asan_memcpy+0x20/0x60
  nsh_hdr_from_nlattr+0x1dd/0x6a0 [openvswitch]
  push_nsh+0x82/0x120 [openvswitch]
  do_execute_actions+0x1405/0x2840 [openvswitch]
  ovs_execute_actions+0xd5/0x3b0 [openvswitch]
  ovs_packet_cmd_execute+0x949/0xdb0 [openvswitch]
  genl_family_rcv_msg_doit+0x1d6/0x2b0
  genl_family_rcv_msg+0x336/0x580
  genl_rcv_msg+0x9f/0x130
  netlink_rcv_skb+0x11f/0x370
  genl_rcv+0x24/0x40
  netlink_unicast+0x73e/0xaa0
  netlink_sendmsg+0x744/0xbf0
  __sys_sendto+0x3d6/0x450
  do_syscall_64+0x79/0x2c0
  entry_SYSCALL_64_after_hwframe+0x76/0x7e
  </TASK>

Let's add some checks that the attribute is properly sized and it's
the only one attribute inside the action.  Technically, there is no
real reason for OVS_KEY_ATTR_NSH to be there, as we know that we're
pushing an NSH header already, it just creates extra nesting, but
that's how uAPI works today.  So, keeping as it is.

Fixes: b2d0f5d5dc53 ("openvswitch: enable NSH support")
Reported-by: Junvy Yang <zhuque@tencent.com>
Signed-off-by: Ilya Maximets <i.maximets@ovn.org>
Acked-by: Eelco Chaudron echaudro@redhat.com
Reviewed-by: Aaron Conole <aconole@redhat.com>
Link: https://patch.msgid.link/20251204105334.900379-1-i.maximets@ovn.org
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
Missing validation of the middle attribute (OVS_KEY_ATTR_NSH) inside the OVS_ACTION_ATTR_PUSH_NSH action. The `validate_push_nsh()` function did not check the type, size, or exclusivity of the nested attribute, allowing a malformed netlink message to pass validation and later cause a slab-out-of-bounds read during execution.

Here is the patch:

-static bool validate_push_nsh(const struct nlattr *attr, bool log)
+static bool validate_push_nsh(const struct nlattr *a, bool log)
 {
+	struct nlattr *nsh_key = nla_data(a);
 	struct sw_flow_match match;
 	struct sw_flow_key key;

+	/* There must be one and only one NSH header. */
+	if (!nla_ok(nsh_key, nla_len(a)) ||
+	    nla_total_size(nla_len(nsh_key)) != nla_len(a) ||
+	    nla_type(nsh_key) != OVS_KEY_ATTR_NSH)
+		return false;
+
 	ovs_match_init(&match, &key, true, NULL);
-	return !nsh_key_put_from_nlattr(attr, &match, false, true, log);
+	return !nsh_key_put_from_nlattr(nsh_key, &match, false, true, log);
 }


 static int __ovs_nla_copy_actions(struct net *net, const struct nlattr *attr,
 				  const struct sw_flow_key *key,
 				  struct sw_flow_actions **sfa,
 				  __be16 eth_type, __be16 vlan_tci,
 				  u32 mpls_label_count, bool log,
 				  u32 depth)
 {
 	u8 mac_proto = ovs_key_mac_proto(key);
 	const struct nlattr *a;
 	int rem, err;

 	if (depth > OVS_COPY_ACTIONS_MAX_DEPTH)
 		return -EOVERFLOW;

 	nla_for_each_nested(a, attr, rem) {
 		/* Expected argument lengths, (u32)-1 for variable length. */
 		static const u32 action_lens[OVS_ACTION_ATTR_MAX + 1] = {
 			[OVS_ACTION_ATTR_OUTPUT] = sizeof(u32),
 			[OVS_ACTION_ATTR_RECIRC] = sizeof(u32),
 			[OVS_ACTION_ATTR_USERSPACE] = (u32)-1,
 			[OVS_ACTION_ATTR_PUSH_MPLS] = sizeof(struct ovs_action_push_mpls),
 			[OVS_ACTION_ATTR_POP_MPLS] = sizeof(__be16),
 			[OVS_ACTION_ATTR_PUSH_VLAN] = sizeof(struct ovs_action_push_vlan),
 			[OVS_ACTION_ATTR_POP_VLAN] = 0,
 			[OVS_ACTION_ATTR_SET] = (u32)-1,
 			[OVS_ACTION_ATTR_SET_MASKED] = (u32)-1,
 			[OVS_ACTION_ATTR_SAMPLE] = (u32)-1,
 			[OVS_ACTION_ATTR_HASH] = sizeof(struct ovs_action_hash),
 			[OVS_ACTION_ATTR_CT] = (u32)-1,
 			[OVS_ACTION_ATTR_CT_CLEAR] = 0,
 			[OVS_ACTION_ATTR_TRUNC] = sizeof(struct ovs_action_trunc),
 			[OVS_ACTION_ATTR_PUSH_ETH] = sizeof(struct ovs_action_push_eth),
 			[OVS_ACTION_ATTR_POP_ETH] = 0,
 			[OVS_ACTION_ATTR_PUSH_NSH] = (u32)-1,
 			[OVS_ACTION_ATTR_POP_NSH] = 0,
 			[OVS_ACTION_ATTR_METER] = sizeof(u32),
 			[OVS_ACTION_ATTR_CLONE] = (u32)-1,
 			[OVS_ACTION_ATTR_CHECK_PKT_LEN] = (u32)-1,
 			[OVS_ACTION_ATTR_ADD_MPLS] = sizeof(struct ovs_action_add_mpls),
 			[OVS_ACTION_ATTR_DEC_TTL] = (u32)-1,
 			[OVS_ACTION_ATTR_DROP] = sizeof(u32),
 			[OVS_ACTION_ATTR_PSAMPLE] = (u32)-1,
 		};
 		const struct ovs_action_push_vlan *vlan;
 		int type = nla_type(a);
 		bool skip_copy;

 		if (type > OVS_ACTION_ATTR_MAX ||
 		    (action_lens[type] != nla_len(a) &&
 		     action_lens[type] != (u32)-1))
 			return -EINVAL;

 		skip_copy = false;
 		switch (type) {
 		case OVS_ACTION_ATTR_UNSPEC:
 			return -EINVAL;

 		case OVS_ACTION_ATTR_USERSPACE:
 			err = validate_userspace(a);
 			if (err)
 				return err;
 			break;

 		case OVS_ACTION_ATTR_OUTPUT:
 			if (nla_get_u32(a) >= DP_MAX_PORTS)
 				return -EINVAL;
 			break;

 		case OVS_ACTION_ATTR_TRUNC: {
 			const struct ovs_action_trunc *trunc = nla_data(a);

 			if (trunc->max_len < ETH_HLEN)
 				return -EINVAL;
 			break;
 		}

 		case OVS_ACTION_ATTR_HASH: {
 			const struct ovs_action_hash *act_hash = nla_data(a);

 			switch (act_hash->hash_alg) {
 			case OVS_HASH_ALG_L4:
 				fallthrough;
 			case OVS_HASH_ALG_SYM_L4:
 				break;
 			default:
 				return  -EINVAL;
 			}

 			break;
 		}

 		case OVS_ACTION_ATTR_POP_VLAN:
 			if (mac_proto != MAC_PROTO_ETHERNET)
 				return -EINVAL;
 			vlan_tci = htons(0);
 			break;

 		case OVS_ACTION_ATTR_PUSH_VLAN:
 			if (mac_proto != MAC_PROTO_ETHERNET)
 				return -EINVAL;
 			vlan = nla_data(a);
 			if (!eth_type_vlan(vlan->vlan_tpid))
 				return -EINVAL;
 			if (!(vlan->vlan_tci & htons(VLAN_CFI_MASK)))
 				return -EINVAL;
 			vlan_tci = vlan->vlan_tci;
 			break;

 		case OVS_ACTION_ATTR_RECIRC:
 			break;

 		case OVS_ACTION_ATTR_ADD_MPLS: {
 			const struct ovs_action_add_mpls *mpls = nla_data(a);

 			if (!eth_p_mpls(mpls->mpls_ethertype))
 				return -EINVAL;

 			if (mpls->tun_flags & OVS_MPLS_L3_TUNNEL_FLAG_MASK) {
 				if (vlan_tci & htons(VLAN_CFI_MASK) ||
 				    (eth_type != htons(ETH_P_IP) &&
 				     eth_type != htons(ETH_P_IPV6) &&
 				     eth_type != htons(ETH_P_ARP) &&
 				     eth_type != htons(ETH_P_RARP) &&
 				     !eth_p_mpls(eth_type)))
 					return -EINVAL;
 				mpls_label_count++;
 			} else {
 				if (mac_proto == MAC_PROTO_ETHERNET) {
 					mpls_label_count = 1;
 					mac_proto = MAC_PROTO_NONE;
 				} else {
 					mpls_label_count++;
 				}
 			}
 			eth_type = mpls->mpls_ethertype;
 			break;
 		}

 		case OVS_ACTION_ATTR_PUSH_MPLS: {
 			const struct ovs_action_push_mpls *mpls = nla_data(a);

 			if (!eth_p_mpls(mpls->mpls_ethertype))
 				return -EINVAL;
 			/* Prohibit push MPLS other than to a white list
 			 * for packets that have a known tag order.
 			 */
 			if (vlan_tci & htons(VLAN_CFI_MASK) ||
 			    (eth_type != htons(ETH_P_IP) &&
 			     eth_type != htons(ETH_P_IPV6) &&
 			     eth_type != htons(ETH_P_ARP) &&
 			     eth_type != htons(ETH_P_RARP) &&
 			     !eth_p_mpls(eth_type)))
 				return -EINVAL;
 			eth_type = mpls->mpls_ethertype;
 			mpls_label_count++;
 			break;
 		}

 		case OVS_ACTION_ATTR_POP_MPLS: {
 			__be16  proto;
 			if (vlan_tci & htons(VLAN_CFI_MASK) ||
 			    !eth_p_mpls(eth_type))
 				return -EINVAL;

 			/* Disallow subsequent L2.5+ set actions and mpls_pop
 			 * actions once the last MPLS label in the packet is
 			 * popped as there is no check here to ensure that
 			 * the new eth type is valid and thus set actions could
 			 * write off the end of the packet or otherwise corrupt
 			 * it.
 			 *
 			 * Support for these actions is planned using packet
 			 * recirculation.
 			 */
 			proto = nla_get_be16(a);

 			if (proto == htons(ETH_P_TEB) &&
 			    mac_proto != MAC_PROTO_NONE)
 				return -EINVAL;

 			mpls_label_count--;

 			if (!eth_p_mpls(proto) || !mpls_label_count)
 				eth_type = htons(0);
 			else
 				eth_type =  proto;

 			break;
 		}

 		case OVS_ACTION_ATTR_SET:
 			err = validate_set(a, key, sfa,
 					   &skip_copy, mac_proto, eth_type,
 					   false, log);
 			if (err)
 				return err;
 			break;

 		case OVS_ACTION_ATTR_SET_MASKED:
 			err = validate_set(a, key, sfa,
 					   &skip_copy, mac_proto, eth_type,
 					   true, log);
 			if (err)
 				return err;
 			break;

 		case OVS_ACTION_ATTR_SAMPLE: {
 			bool last = nla_is_last(a, rem);

 			err = validate_and_copy_sample(net, a, key, sfa,
 						       eth_type, vlan_tci,
 						       mpls_label_count,
 						       log, last, depth);
 			if (err)
 				return err;
 			skip_copy = true;
 			break;
 		}

 		case OVS_ACTION_ATTR_CT:
 			err = ovs_ct_copy_action(net, a, key, sfa, log);
 			if (err)
 				return err;
 			skip_copy = true;
 			break;

 		case OVS_ACTION_ATTR_CT_CLEAR:
 			break;

 		case OVS_ACTION_ATTR_PUSH_ETH:
 			/* Disallow pushing an Ethernet header if one
 			 * is already present */
 			if (mac_proto != MAC_PROTO_NONE)
 				return -EINVAL;
 			mac_proto = MAC_PROTO_ETHERNET;
 			break;

 		case OVS_ACTION_ATTR_POP_ETH:
 			if (mac_proto != MAC_PROTO_ETHERNET)
 				return -EINVAL;
 			if (vlan_tci & htons(VLAN_CFI_MASK))
 				return -EINVAL;
 			mac_proto = MAC_PROTO_NONE;
 			break;

 		case OVS_ACTION_ATTR_PUSH_NSH:
 			if (mac_proto != MAC_PROTO_ETHERNET) {
 				u8 next_proto;

 				next_proto = tun_p_from_eth_p(eth_type);
 				if (!next_proto)
 					return -EINVAL;
 			}
 			mac_proto = MAC_PROTO_NONE;
-			if (!validate_push_nsh(nla_data(a), log))
+			if (!validate_push_nsh(a, log))
 				return -EINVAL;
 			break;

 		case OVS_ACTION_ATTR_POP_NSH: {
 			__be16 inner_proto;

 			if (eth_type != htons(ETH_P_NSH))
 				return -EINVAL;
 			inner_proto = tun_p_to_eth_p(key->nsh.base.np);
 			if (!inner_proto)
 				return -EINVAL;
 			if (key->nsh.base.np == TUN_P_ETHERNET)
 				mac_proto = MAC_PROTO_ETHERNET;
 			else
 				mac_proto = MAC_PROTO_NONE;
 			break;
 		}

 		case OVS_ACTION_ATTR_METER:
 			/* Non-existent meters are simply ignored.  */
 			break;

 		case OVS_ACTION_ATTR_CLONE: {
 			bool last = nla_is_last(a, rem);

 			err = validate_and_copy_clone(net, a, key, sfa,
 						      eth_type, vlan_tci,
 						      mpls_label_count,
 						      log, last, depth);
 			if (err)
 				return err;
 			skip_copy = true;
 			break;
 		}

 		case OVS_ACTION_ATTR_CHECK_PKT_LEN: {
 			bool last = nla_is_last(a, rem);

 			err = validate_and_copy_check_pkt_len(net, a, key, sfa,
 							      eth_type,
 							      vlan_tci,
 							      mpls_label_count,
 							      log, last,
 							      depth);
 			if (err)
 				return err;
 			skip_copy = true;
 			break;
 		}

 		case OVS_ACTION_ATTR_DEC_TTL:
 			err = validate_and_copy_dec_ttl(net, a, key, sfa,
 							eth_type, vlan_tci,
 							mpls_label_count, log,
 							depth);
 			if (err)
 				return err;
 			skip_copy = true;
 			break;

 		case OVS_ACTION_ATTR_DROP:
 			if (!nla_is_last(a, rem))
 				return -EINVAL;
 			break;

 		case OVS_ACTION_ATTR_PSAMPLE:
 			err = validate_psample(a);
 			if (err)
 				return err;
 			break;

 		default:
 			OVS_NLERR(log, "Unknown Action type %d", type);
 			return -EINVAL;
 		}
 		if (!skip_copy) {
 			err = copy_action(a, sfa, log);
 			if (err)
 				return err;
 		}
 	}

 	if (rem > 0)
 		return -EINVAL;

 	return 0;
 }



Provide a response strictly in the following format:

The code statements that lead to the bug are:
<text>
<text>
...
<text>
Reason:
<text>
The code statements that fix the bug are:
<text>
